{
  "decisions": [
    {
      "decision": "domain_of_start_times",
      "evidence": "\"The start time of each operation must be non-negative\"",
      "options": [
        "NonNegativeReals",
        "NonNegativeIntegers"
      ],
      "plausibility": [
        0.7,
        0.3
      ],
      "majority_option": "NonNegativeReals"
    },
    {
      "decision": "domain_of_makespan_variable",
      "evidence": "\"The total completion time, or makespan, is defined as the maximum completion time across all operations\"",
      "options": [
        "NonNegativeReals",
        "NonNegativeIntegers"
      ],
      "plausibility": [
        0.7,
        0.3
      ],
      "majority_option": "NonNegativeReals"
    },
    {
      "decision": "makespan_definition_direction",
      "evidence": "\"the makespan, is defined as the maximum completion time across all operations\"",
      "options": [
        "Cmax >= s[j,o] + p for all operations (lower-bounding)",
        "Cmax = max over operations of s[j,o] + p (equality)"
      ],
      "plausibility": [
        0.85,
        0.15
      ],
      "majority_option": "Cmax >= s[j,o] + p for all operations (lower-bounding)"
    },
    {
      "decision": "precedence_gap_direction",
      "evidence": "\"the start time of the second operation in each job must be at least 1 unit of time after the start time of the first operation in the same job\"",
      "options": [
        "s[j,2] >= s[j,1] + 1",
        "s[j,2] >= s[j,1] + 1 with strict > (i.e. >= 1+epsilon)"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "s[j,2] >= s[j,1] + 1"
    },
    {
      "decision": "big_M_value",
      "evidence": "\"A large constant value of 100,000 is used to enforce the order of operations on shared machines\"",
      "options": [
        "M = 100000",
        "M = tighter bound (e.g. sum of processing times)"
      ],
      "plausibility": [
        0.9,
        0.1
      ],
      "majority_option": "M = 100000"
    },
    {
      "decision": "objective_sense",
      "evidence": "\"The objective is to minimize the makespan\"",
      "options": [
        "minimize Cmax",
        "maximize Cmax"
      ],
      "plausibility": [
        0.99,
        0.01
      ],
      "majority_option": "minimize Cmax"
    }
  ]
}
